2. Concrete Prototype (Circle):Implements the Shape interface and represents a specific shape.Contains properties such as color, initialized through a constructor.Implements the clone() method to create a copy with the same properties.Implements the draw() method to define how the circle is rendere
            C++

    #include <iostream>
#include <string>
using namespace std;

// Base interface/class for Shape
class Shape {
public:
    virtual Shape* clone() const = 0;
    virtual void draw() const = 0;
    virtual ~Shape() = default;
};

// Circle implements Shape
class Circle : public Shape {
private:
    string color;

public:
    // Constructor
    Circle(string color) {
        this->color = color;
    }

    // Creates and returns a copy of the circle
    Shape* clone() const override {
        return new Circle(*this);
    }

    // Draws the circle
    void draw() const override {
        cout << "Drawing a " << color << " circle." << endl;
    }
};


            Java

    import java.util.Scanner;

// Define an abstract class Shape with abstract methods clone and draw
abstract class Shape {
    public abstract Shape clone();
    public abstract void draw();
}

// Define a class Circle that extends Shape
class Circle extends Shape {
    private String color;

    // Constructor for Circle
    public Circle(String color) {
        this.color = color;
    }

    // Override the clone method
    public Shape clone() {
        return new Circle(this.color);
    }

    // Override the draw method
    public void draw() {
        System.out.println("Drawing a " + this.color + " circle.");
    }
}

// Main class to test the functionality
public class Main {
    public static void main(String[] args) {
        Circle circle = new Circle("red");
        circle.draw();
        Circle clonedCircle = circle.clone();
        clonedCircle.draw();
    }
}


