4. Main Class (PrototypeExample):Creates a concrete prototype (circlePrototype) with predefined properties.Passes the prototype to ShapeClient.Uses the client to create a new shape by cloning the prototype.Calls the draw() method on the cloned object to display the result.
            C++

    #include <iostream>
#include <string>
using namespace std;

// Prototype interface
class Shape {
public:
    virtual Shape* clone() = 0;  // Make a copy of itself
    virtual void draw() = 0;    // Draw the shape
};

// Concrete prototype
class Circle : public Shape {
private:
    string color;

public:
    Circle(string color) : color(color) {}

    // This creates a copy of the circle.
    Shape* clone() override {
        return new Circle(this->color);
    }

    // This is how a circle draws itself.
    void draw() override {
        cout << "Drawing a " << color << " circle." << endl;
    }
};

// Client code
class ShapeClient {
private:
    Shape* shapePrototype;

public:
    ShapeClient(Shape* shapePrototype) : shapePrototype(shapePrototype) {}

    // This method creates a new shape using the prototype.
    Shape* createShape() {
        return shapePrototype->clone();
    }
};

// Main class
int main() {
    // Create a concrete prototype (a red circle).
    Shape* circlePrototype = new Circle("red");

    // Create a client and give it the prototype.
    ShapeClient client(circlePrototype);

    // Use the prototype to create a new shape (a red circle).
    Shape* redCircle = client.createShape();

    // Draw the newly created red circle.
    redCircle->draw();

    delete circlePrototype;
    delete redCircle;
    return 0;
}


            Java

    // Prototype interface
interface Shape {
    Shape clone();  // Make a copy of itself
    void draw();    // Draw the shape
}

// Concrete prototype
class Circle implements Shape {
    private String color;

    // When you create a circle, you give it a color.
    public Circle(String color) {
        this.color = color;
    }

    // This creates a copy of the circle.
    @Override
    public Shape clone() {
        return new Circle(this.color);
    }

    // This is how a circle draws itself.
    @Override
    public void draw() {
        System.out.println("Drawing a " + color + " circle.");
    }
}

// Client code
class ShapeClient {
    private Shape shapePrototype;

    // When you create a client, you give it a prototype (a shape).
    public ShapeClient(Shape shapePrototype) {
        this.shapePrototype = shapePrototype;
    }

    // This method creates a new shape using the prototype.
    public Shape createShape() {
        return shapePrototype.clone();
    }
}

// Main class
public class PrototypeExample {
    public static void main(String[] args) {
        // Create a concrete prototype (a red circle).
        Shape circlePrototype = new Circle("red");

        // Create a client and give it the prototype.
        ShapeClient client = new ShapeClient(circlePrototype);

        // Use the prototype to create a new shape (a red circle).
        Shape redCircle = client.createShape();

        // Draw the newly created red circle.
        redCircle.draw();
    }
}


            Python

    from abc import ABC, abstractmethod

# Prototype interface
class Shape(ABC):
    @abstractmethod
    def clone(self):
        """Make a copy of itself"""
        pass

    @abstractmethod
    def draw(self):
        """Draw the shape"""
        pass

# Concrete prototype
class Circle(Shape):
    def __init__(self, color):
        self.color = color

    # This creates a copy of the circle.
    def clone(self):
        return Circle(self.color)

    # This is how a circle draws itself.
    def draw(self):
        print(f'Drawing a {self.color} circle.')

# Client code
class ShapeClient:
    def __init__(self, shape_prototype):
        self.shape_prototype = shape_prototype

    # This method creates a new shape using the prototype.
    def create_shape(self):
        return self.shape_prototype.clone()

# Main class
if __name__ == '__main__':
    # Create a concrete prototype (a red circle).
    circle_prototype = Circle('red')

    # Create a client and give it the prototype.
    client = ShapeClient(circle_prototype)

    # Use the prototype to create a new shape (a red circle).
    red_circle = client.create_shape()

    # Draw the newly created red circle.
    red_circle.draw()


